SELECT *
FROM comum.unidade

 SELECT pe.id, pe.id_papel, pe.id_usuario, p.descricao, p.nome, und.nome AS nome_unidade
FROM comum.permissao pe
JOIN comum.papel p ON
p.id = pe.id_papel
JOIN comum.usuario u ON
u.id_usuario = pe.id_usuario
