SELECT un
FROM comum.papel pa, comum.permissao pe
LEFT JOIN comum.usuario a ON
(pe.id_atribuidor = a.id_usuario)
LEFT JOIN comum.unidade up ON
(pe.id_unidade_papel = up.id_unidade), comum.subsistema ss, comum.usuario u, comum.pessoa p, comum.unidade un, comum.sistema si
WHERE pa.id = pe.id_papel
AND pa.id_subsistema = ss.id
AND pe.id_usuario = u.id_usuario
AND pa.id_sistema = si.id
AND u.id_pessoa = p.id_pessoa
AND u.id_unidade = un.id_unidade
AND pe.id_usuario IN ( 104908, 105087, 105123, 105024, 105115, 105080, 104884, 105083, 104988, 104913, 104924, 104940, 105110, 105106, 105097, 105091, 104945, 104923, 105113, 104897, 104902, 105078, 104939, 104883, 105090, 104888, 105023, 105070, 105029, 104885, 105068, 105125, 104990, 105109, 105064, 104916, 104930, 105082, 104942, 104949, 104987, 104927, 104915, 105084, 105062, 104922, 105100, 104896, 104890, 105075, 104948, 105086, 105074, 105081, 104937, 104921, 105104, 104933, 105120, 104914, 104932, 104899, 104900, 104989, 104944, 104926, 104891, 104893, 104886, 104954, 105063, 104936, 105095, 105122, 104952, 105105, 105026, 104938, 104919, 104950, 105111, 105117, 105096, 105124, 105088, 105092, 105079, 104901, 105116, 105089, 104909, 104928, 104941, 105077, 105099, 105093, 105107, 105094, 104889, 105027, 104929, 104917, 105118, 104931, 104947, 105085, 104951, 105066, 104892, 104907, 104953, 105073, 104925, 104898, 105069, 105025, 104946, 105101, 105119, 104911, 104943, 105126, 105114, 105067, 105098, 104935, 105102, 105121, 105071, 104918, 104934, 105072, 105076, 105065, 104895, 104920, 105108, 1, 104904, 104887, 104882, 104903, 104894, 104912, 105028, 104905, 105103, 105112, 104906, 104910 );
